  out[1] += (0.8660254037844386*X[4]*xbx[4]+0.8660254037844386*X[2]*xbx[3]+0.8660254037844386*X[1]*xbx[1]+0.8660254037844386*X[0]*xbx[0])*dx10*wvpar+(0.25*xbx[4]*X[8]+0.25*xbx[3]*X[6]+0.25*xbx[1]*X[5]+0.25*xbx[0]*X[3])*dvpar*dx10+(0.8660254037844386*ux[3]*X[4]+0.8660254037844386*X[2]*ux[2]+0.8660254037844386*X[1]*ux[1]+0.8660254037844386*X[0]*ux[0])*dx10; 
