  out[6] += (0.8660254037844386*xby[4]*X[8]+0.8660254037844386*xby[3]*X[6]+0.8660254037844386*xby[1]*X[5]+0.8660254037844386*xby[0]*X[3])*dx11*wvpar+(0.22360679774997896*xby[4]*X[11]+0.22360679774997902*xby[3]*X[10]+0.22360679774997902*xby[1]*X[9]+0.22360679774997896*xby[0]*X[7]+0.25*X[4]*xby[4]+0.25*X[2]*xby[3]+0.25*X[1]*xby[1]+0.25*X[0]*xby[0])*dvpar*dx11+(0.8660254037844386*uy[3]*X[8]+0.8660254037844386*uy[2]*X[6]+0.8660254037844386*uy[1]*X[5]+0.8660254037844386*uy[0]*X[3])*dx11; 
  out[8] += (0.7745966692414833*xby[5]*X[8]+0.8660254037844386*xby[3]*X[8]+0.8660254037844386*xby[4]*X[6]+0.7745966692414833*xby[2]*X[5]+0.8660254037844386*xby[0]*X[5]+0.8660254037844386*xby[1]*X[3])*dx11*wvpar+(0.7745966692414833*xbx[7]*X[8]+0.8660254037844386*xbx[1]*X[8]+0.7745966692414833*X[6]*xbx[6]+0.8660254037844386*xbx[0]*X[6]+0.8660254037844386*xbx[4]*X[5]+0.8660254037844386*X[3]*xbx[3])*dx10*wvpar+(0.2*xby[5]*X[11]+0.22360679774997896*xby[3]*X[11]+0.22360679774997902*xby[4]*X[10]+0.2*xby[2]*X[9]+0.22360679774997902*xby[0]*X[9]+0.22360679774997896*xby[1]*X[7]+0.22360679774997896*X[4]*xby[5]+0.25*X[2]*xby[4]+0.25*xby[3]*X[4]+0.22360679774997896*X[1]*xby[2]+0.25*X[0]*xby[1]+0.25*xby[0]*X[1])*dvpar*dx11+(0.8660254037844386*uy[2]*X[8]+0.8660254037844386*uy[3]*X[6]+0.8660254037844386*uy[0]*X[5]+0.8660254037844386*uy[1]*X[3])*dx11+(0.2*xbx[7]*X[11]+0.22360679774997896*xbx[1]*X[11]+0.2*xbx[6]*X[10]+0.22360679774997902*xbx[0]*X[10]+0.22360679774997902*xbx[4]*X[9]+0.22360679774997896*X[4]*xbx[7]+0.22360679774997896*xbx[3]*X[7]+0.22360679774997896*X[2]*xbx[6]+0.25*X[1]*xbx[4]+0.25*xbx[1]*X[4]+0.25*X[0]*xbx[3]+0.25*xbx[0]*X[2])*dvpar*dx10+(0.8660254037844386*ux[1]*X[8]+0.8660254037844386*ux[0]*X[6]+0.8660254037844386*ux[3]*X[5]+0.8660254037844386*ux[2]*X[3])*dx10; 
