  out[10] += (0.8660254037844387*xby[4]*X[11]+0.8660254037844386*xby[3]*X[10]+0.8660254037844386*xby[1]*X[9]+0.8660254037844387*xby[0]*X[7])*dx11*wvpar+(0.22360679774997902*xby[4]*X[8]+0.22360679774997902*xby[3]*X[6]+0.22360679774997902*xby[1]*X[5]+0.22360679774997902*xby[0]*X[3])*dvpar*dx11+(0.8660254037844387*uy[3]*X[11]+0.8660254037844386*uy[2]*X[10]+0.8660254037844386*uy[1]*X[9]+0.8660254037844387*uy[0]*X[7])*dx11; 
  out[11] += (0.7745966692414833*xby[5]*X[11]+0.8660254037844386*xby[3]*X[11]+0.8660254037844387*xby[4]*X[10]+0.7745966692414834*xby[2]*X[9]+0.8660254037844387*xby[0]*X[9]+0.8660254037844386*xby[1]*X[7])*dx11*wvpar+(0.7745966692414833*xbx[7]*X[11]+0.8660254037844386*xbx[1]*X[11]+0.7745966692414834*xbx[6]*X[10]+0.8660254037844387*xbx[0]*X[10]+0.8660254037844387*xbx[4]*X[9]+0.8660254037844386*xbx[3]*X[7])*dx10*wvpar+(0.2*xby[5]*X[8]+0.22360679774997896*xby[3]*X[8]+0.22360679774997896*xby[4]*X[6]+0.2*xby[2]*X[5]+0.22360679774997896*xby[0]*X[5]+0.22360679774997896*xby[1]*X[3])*dvpar*dx11+(0.8660254037844386*uy[2]*X[11]+0.8660254037844387*uy[3]*X[10]+0.8660254037844387*uy[0]*X[9]+0.8660254037844386*uy[1]*X[7])*dx11+(0.2*xbx[7]*X[8]+0.22360679774997896*xbx[1]*X[8]+0.2*X[6]*xbx[6]+0.22360679774997896*xbx[0]*X[6]+0.22360679774997896*xbx[4]*X[5]+0.22360679774997896*X[3]*xbx[3])*dvpar*dx10+(0.8660254037844386*ux[1]*X[11]+0.8660254037844387*ux[0]*X[10]+0.8660254037844387*ux[3]*X[9]+0.8660254037844386*ux[2]*X[7])*dx10; 
